// AEOS Client Intake v0.1 — decision rule D3 from SPEC.md §3.
// overdue = status in {New, Contacted} AND now > sla_due_at.
// Returns a single digest item, or [] when nothing is overdue (ends the run).

const OPEN_STATUSES = ['New', 'Contacted'];
const now = new Date();

const overdue = $input
  .all()
  .map((item) => item.json)
  .filter((row) => {
    const status = (row.status || '').trim();
    if (!OPEN_STATUSES.includes(status)) return false;

    const due = new Date(row.sla_due_at);
    if (Number.isNaN(due.getTime())) return false;

    return now > due;
  })
  .sort((a, b) => new Date(a.sla_due_at) - new Date(b.sla_due_at));

if (overdue.length === 0) {
  return [];
}

const hoursLate = (row) =>
  Math.floor((now - new Date(row.sla_due_at)) / (60 * 60 * 1000));

const lines = overdue.map(
  (row) =>
    `- [${row.priority}] ${row.organization} — ${row.full_name} <${row.work_email}> · ${hoursLate(row)}h past deadline · status "${row.status}" · ${row.submission_id}`,
);

return [
  {
    json: {
      overdue_count: overdue.length,
      p1_count: overdue.filter((row) => row.priority === 'P1').length,
      generated_at: now.toISOString(),
      digest: lines.join('\n'),
    },
  },
];

